package com.guocheng.mediapocket;
import android.app.Activity;import android.os.*;import org.json.*;
/** Applies explicit IDs only to the source carrying them, after the decoder reports those IDs. */
final class TrackSelection {
 static JSONObject stream(Activity a){Object value=OnlineSubtitleSearch.field(a,"stream");if(value instanceof JSONObject)return (JSONObject)value;try{return new JSONObject(a.getIntent().getStringExtra("stream"));}catch(Exception e){return new JSONObject();}}
 static boolean hasAudio(JSONObject s){return s.has("mp.audioTrack");}
 static boolean hasSubtitle(JSONObject s){return s.has("mp.subtitleTrack");}
 static boolean contains(Object tracks,int target){if(target==-1)return true;if(tracks instanceof Object[])for(Object track:(Object[])tracks){if(track==null)continue;Object id=trackId(track);if(id instanceof Number&&((Number)id).intValue()==target)return true;}return false;}
 static Object trackId(Object track){for(Class<?> c=track.getClass();c!=null;c=c.getSuperclass())try{java.lang.reflect.Field field=c.getDeclaredField("id");field.setAccessible(true);return field.get(track);}catch(Exception ignored){}return null;}
 static boolean sameSource(JSONObject one,JSONObject two){return one==two||one.optString("url").equals(two.optString("url"))&&one.optString("infoHash").equals(two.optString("infoHash"))&&one.optInt("fileIdx",-1)==two.optInt("fileIdx",-1);}
 static void attach(Activity a){JSONObject source=stream(a);if(!hasAudio(source)&&!hasSubtitle(source))return;Object initial=OnlineSubtitleSearch.field(a,"video");Handler handler=new Handler(Looper.getMainLooper());handler.postDelayed(new Runnable(){int tries;boolean audioDone=!hasAudio(source),subtitleDone=!hasSubtitle(source);public void run(){if(a.isFinishing()||a.isDestroyed()||++tries>40||!sameSource(stream(a),source))return;Object video=OnlineSubtitleSearch.field(a,"video");if(initial!=null&&video!=initial)return;if(video!=null)try{if(!audioDone){int target=source.optInt("mp.audioTrack",-1);Object tracks=OnlineSubtitleSearch.call(video,"audioTracks",new Class<?>[0]);if(contains(tracks,target)){OnlineSubtitleSearch.call(video,"audio",new Class<?>[]{int.class},target);audioDone=true;}}if(!subtitleDone){Object player=OnlineSubtitleSearch.field(video,"player");if(player!=null){int target=source.optInt("mp.subtitleTrack",-1);Object tracks=OnlineSubtitleSearch.call(player,"getSpuTracks",new Class<?>[0]);if(contains(tracks,target)){OnlineSubtitleSearch.call(player,"setSpuTrack",new Class<?>[]{int.class},target);subtitleDone=true;}}}}catch(Exception ignored){}if(!audioDone||!subtitleDone)handler.postDelayed(this,1000);}},2000);}
}
